<template><section class="shop-page"><header class="shop-heading"><div><span class="shop-eyebrow">CATÁLOGO DO ESTABELECIMENTO</span><h1>Produtos</h1><p>Defina o que sua loja oferece, quanto custa e se está disponível.</p></div><button class="shop-primary" @click="open()"><i class="ri-add-line"></i> Novo produto</button></header><div v-if="notice" class="shop-alert" role="status">{{notice}}</div><div v-if="shop.error" class="shop-alert error" role="alert">{{shop.error}}</div><div class="shop-panel"><div class="shop-toolbar"><label class="shop-search"><i class="ri-search-line"></i><input v-model="query" aria-label="Buscar produtos" placeholder="Buscar por nome, código ou categoria…"/></label><select v-model="filter" aria-label="Disponibilidade"><option value="ALL">Todos os produtos</option><option value="PENDING_PRICE">Sem preço de venda</option><option v-for="(label,value) in availability" :key="value" :value="value">{{label}}</option></select><button class="shop-secondary" :disabled="shop.loading" @click="shop.load"><i class="ri-refresh-line"></i> Atualizar</button></div><div class="shop-table"><table><thead><tr><th>Produto</th><th>Categoria</th><th>Preço de venda</th><th>Disponibilidade</th><th><span class="shop-sr-only">Editar</span></th></tr></thead><tbody><tr v-for="p in visible" :key="p.id"><td><div class="shop-product"><span><i class="ri-shopping-bag-3-line"></i></span><div><strong>{{p.name}}</strong><small>{{p.sku}} · {{p.unit}}</small></div></div></td><td>{{p.category||'Sem categoria'}}</td><td class="shop-price">{{money(p.price_cents)}}</td><td><span class="shop-status" :class="p.availability"><i></i>{{availability[p.availability]}}</span></td><td><button class="shop-edit" :aria-label="'Editar '+p.name" @click="open(p)"><i class="ri-edit-line"></i></button></td></tr></tbody></table><div v-if="!visible.length" class="shop-empty"><i class="ri-box-3-line"></i><h3>{{shop.products.length?'Nenhum produto encontrado':'Seu catálogo começa aqui'}}</h3><p>{{shop.products.length?'Ajuste os filtros para encontrar o que procura.':'Cadastre o primeiro produto ou importe os itens de uma NF-e.'}}</p><button v-if="!shop.products.length" class="shop-primary" @click="open()">Cadastrar primeiro produto</button></div></div><footer>{{visible.length}} de {{shop.products.length}} produtos<span>Preços em reais (BRL)</span></footer></div><ProductEditor v-if="editor" :product="editing" @close="editor=false" @saved="saved"/></section></template>
<script setup>
import { computed,onMounted,ref } from 'vue'
import { useRoute } from 'vue-router'
import { useShopStore } from '@/stores/shop.store'
import { availability,money,normalize } from '@/utils/shop'
import ProductEditor from '@/components/shop/ProductEditor.vue'
const shop=useShopStore(),route=useRoute(),editor=ref(false),editing=ref(null),query=ref(''),filter=ref('ALL'),notice=ref('')
const visible=computed(()=>shop.products.filter(p=>(filter.value==='ALL'||filter.value==='PENDING_PRICE'&&p.price_cents==null||p.availability===filter.value)&&normalize(p.name+' '+p.sku+' '+p.category).includes(normalize(query.value))))
function open(product=null){editing.value=product;editor.value=true;notice.value=''}
async function saved(){editor.value=false;notice.value='Produto salvo. A alteração foi registrada no histórico.';await shop.load()}
onMounted(()=>{if(route.query.novo==='1')open()})
</script>
